/**
 * @method
 * @name grd_pageResult_oncellclick
 * @description grd_pageResult 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_pageResult_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_pageResult');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_pageResult */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; } /* 수동 전환 필요: fn_pubofrSchdl('${entity.bzProcsNo}','${entity.ldMktTpCd}','${entity.listTpClssCd}','save' );return false; (EL 미해석) · fn_pubofrSchdl('${entity.bzProcsNo}','${entity.ldMktTpCd}','${entity.listTpClssCd}' ,'save');return false; (EL 미해석) · fn_pubofrSchdl('${entity.bzProcsNo}','${entity.ldMktTpCd}','${entity.listTpClssCd}' ,'save' );return false; (EL 미해석) · fn_pubofrSchdl('${entity.bzProcsNo}','${entity.ldMktTpCd}','${entity.listTpClssCd}' ,'save' );return false; (EL 미해석) · fn_prtDepo('${entity.bzProcsNo}','${entity.ldMktTpCd}','${entity.listTpClssCd}','save');return false; (EL 미해석) · fn_prtDepo('${entity.bzProcsNo}' ,'${entity.ldMktTpCd}','${entity.listTpClssCd}','save');return false; (EL 미해석) · fn_prtDepo('${entity.bzProcsNo}','${entity.ldMktTpCd}','${entity.listTpClssCd}','save');return false; (EL 미해석) · fn_prtDepo('${entity.bzProcsNo}','${entity.ldMktTpCd}','${entity.listTpClssCd}' ,'save' );return false; (EL 미해석) · fn_cap('${entity.bzProcsNo}','${entity.ldMktTpCd}','${entity.listTpClssCd}','save');return false; (EL 미해석) · fn_cap('${entity.bzProcsNo}' ,'${entity.ldMktTpCd}','${entity.listTpClssCd}','save');return false; (EL 미해석) · fn_cap('${entity.bzProcsNo}','${entity.ldMktTpCd}','${entity.listTpClssCd}','save');return false; (EL 미해석) · fn_cap('${entity.bzProcsNo}','${entity.ldMktTpCd}','${entity.listTpClssCd}' ,'save' );return false; (EL 미해석) · fn_submit('${entity.bzProcsNo}','${entity.step1DtlStat}|${entity.stkCntYn}|${entity.stkIsuYn}|${entity.step2DtlStat}|${entity.step3DtlStat}');return false; (EL 미해석) · fn_noSubmit('${entity.capContnWrtYn}','${entity.fncContnWrtYn}','${entity.stkContnWrtYn}','${entity.instInvstYn}','${entity.cbIsuYn}','${entity.bwIsuYn}','${entity.corpbndIsuCorrYn}','${entity.ventcapCorrYn}','${entity.mergeRelContnWrtYn}','${entity.ldMktTpCd}');return false; (EL 미해석) · fn_submit('${entity.bzProcsNo}','${entity.step1DtlStat}|${entity.stkCntYn}|${entity.stkIsuYn}|${entity.step2DtlStat}|${entity.step3DtlStat}');return false; (EL 미해석) · fn_noSubmit('${entity.capContnWrtYn}','${entity.fncContnWrtYn}','${entity.stkContnWrtYn}','${entity.instInvstYn}','${entity.cbIsuYn}','${entity.bwIsuYn}','${entity.corpbndIsuCorrYn}','${entity.ventcapCorrYn}','${entity.mergeRelContnWrtYn}','${entity.ldMktTpCd}');return false; (EL 미해석) · fn_submit('${entity.bzProcsNo}','${entity.step1DtlStat}|${entity.stkCntYn}|${entity.stkIsuYn}|${entity.step2DtlStat}|${entity.step3DtlStat}');return false; (EL 미해석) · fn_noSubmit('${entity.capContnWrtYn}','${entity.fncContnWrtYn}','${entity.stkContnWrtYn}','${entity.instInvstYn}','${entity.cbIsuYn}','${entity.bwIsuYn}','${entity.corpbndIsuCorrYn}','${entity.ventcapCorrYn}','${entity.mergeRelContnWrtYn}','${entity.ldMktTpCd}');return false; (EL 미해석) · openAdjReqPop('${entity.bzProcsNo}','120');return false; (EL 미해석) · openAdjReqPop('${entity.bzProcsNo}','120');return false; (EL 미해석) · openAdjReqPop('${entity.bzProcsNo}','120');return false; (EL 미해석) · openAdjReqPop('${entity.bzProcsNo}','120');return false; (EL 미해석) */
        if (r["step1DtlStat"] === '32') { await scwin.pubofrSchdl(r["bzProcsNo"], r["ldMktTpCd"], r["listTpClssCd"], "view"); return; }
        if (r["step1DtlStat"] === '33') { await scwin.pubofrSchdl(r["bzProcsNo"], r["ldMktTpCd"], r["listTpClssCd"], "view"); return; }
        if (r["step1DtlStat"] === '34') { await scwin.pubofrSchdl(r["bzProcsNo"], r["ldMktTpCd"], r["listTpClssCd"], "view"); return; }
        if (r["step1DtlStat"] === '36') { await scwin.pubofrSchdl(r["bzProcsNo"], r["ldMktTpCd"], r["listTpClssCd"], "view"); return; }
        if (r["step1DtlStat"] === '') { await $c.win.alert('기업일반정보를 먼저 작성해주세요.');return false; return; }
        if (r["step3DtlStat"] === '32') { await scwin.prtDepo(r["bzProcsNo"], r["ldMktTpCd"], r["listTpClssCd"], "view"); return; }
        if (r["step3DtlStat"] === '33') { await scwin.prtDepo(r["bzProcsNo"], r["ldMktTpCd"], r["listTpClssCd"], "view"); return; }
        if (r["step3DtlStat"] === '34') { await scwin.prtDepo(r["bzProcsNo"], r["ldMktTpCd"], r["listTpClssCd"], "view"); return; }
        if (r["step3DtlStat"] === '36') { await scwin.prtDepo(r["bzProcsNo"], r["ldMktTpCd"], r["listTpClssCd"], "view"); return; }
        if (r["stkCntYn"] === '') { await scwin.listShrs(r["bzProcsNo"], r["isurCd"]); return; }
        if (r["stkCntYn"] === '30') { await scwin.listShrs(r["bzProcsNo"], r["isurCd"]); return; }
        if (r["stkCntYn"] === '32') { await scwin.listShrs(r["bzProcsNo"], r["isurCd"]); return; }
        if (r["stkCntYn"] === '33') { await scwin.listShrs(r["bzProcsNo"], r["isurCd"]); return; }
        if (r["stkCntYn"] === '34') { await scwin.listShrs(r["bzProcsNo"], r["isurCd"]); return; }
        if (r["stkCntYn"] === '35') { await scwin.listShrs(r["bzProcsNo"], r["isurCd"]); return; }
        if (r["stkCntYn"] === '36') { await scwin.listShrs(r["bzProcsNo"], r["isurCd"]); return; }
        if (r["stkCntYn"] === '37') { await scwin.listShrs(r["bzProcsNo"], r["isurCd"]); return; }
        if (r["stkIsuYn"] === '') { await scwin.newListStkcertIsuStat(r["bzProcsNo"], r["isurCd"]); return; }
        if (r["stkIsuYn"] === '30') { await scwin.newListStkcertIsuStat(r["bzProcsNo"], r["isurCd"]); return; }
        if (r["stkIsuYn"] === '32') { await scwin.newListStkcertIsuStat(r["bzProcsNo"], r["isurCd"]); return; }
        if (r["stkIsuYn"] === '33') { await scwin.newListStkcertIsuStat(r["bzProcsNo"], r["isurCd"]); return; }
        if (r["stkIsuYn"] === '34') { await scwin.newListStkcertIsuStat(r["bzProcsNo"], r["isurCd"]); return; }
        if (r["stkIsuYn"] === '35') { await scwin.newListStkcertIsuStat(r["bzProcsNo"], r["isurCd"]); return; }
        if (r["stkIsuYn"] === '36') { await scwin.newListStkcertIsuStat(r["bzProcsNo"], r["isurCd"]); return; }
        if (r["stkIsuYn"] === '37') { await scwin.newListStkcertIsuStat(r["bzProcsNo"], r["isurCd"]); return; }
        if (r["step2DtlStat"] === '32') { await scwin.cap(r["bzProcsNo"], r["ldMktTpCd"], r["listTpClssCd"], "view"); return; }
        if (r["step2DtlStat"] === '33') { await scwin.cap(r["bzProcsNo"], r["ldMktTpCd"], r["listTpClssCd"], "view"); return; }
        if (r["step2DtlStat"] === '34') { await scwin.cap(r["bzProcsNo"], r["ldMktTpCd"], r["listTpClssCd"], "view"); return; }
        if (r["step2DtlStat"] === '36') { await scwin.cap(r["bzProcsNo"], r["ldMktTpCd"], r["listTpClssCd"], "view"); return; }
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_pageResult.oncellclick' });
    }
};

/**
 * @method
 * @name krxpage_pagenavigator_222_onclick
 * @description krxpage_pagenavigator_222 클릭 이벤트
 * @param {Number} index index
 * @returns {void}
