 */
scwin.krxpage_pagenavigator_222_onclick = async function (index) { const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index; try { $c.util.getComponent('dma_pubofrSchdlReq').set('pageIndex', pi); } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'krxpage_pagenavigator_222.page' }); } await scwin.fncSearch(); };

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_pubofrSchdl
 * @description pubofr Schdl 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_pubofrSchdl = async function () {
    const sbmOptions = {
        id: "tx_fn_pubofrSchdl",
        method: "post",
        action: "/listInvstg/listPrelmInvstg.do",
        ref: "dma_pubofrSchdlReq",
        target: "dlt_pageResult=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

