/**
 * @method
 * @name noSubmit
 * @description no Submit 처리
 * @param {*} v1 v1
 * @param {*} v2 v2
 * @param {*} v3 v3
 * @param {*} v4 v4
 * @param {*} v5 v5
 * @param {*} v6 v6
 * @param {*} v7 v7
 * @param {*} v9 v9
 * @param {*} v0 v0
 * @param {String} ldMktTpCd ldMktTpCd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.noSubmit = async function (v1, v2, v3, v4, v5, v6, v7, v9, v0, ldMktTpCd) {
    let txt = "";
    if (v1 !== 'Y') {
        txt += "자본사항,";
    }
    if (v2 !== 'Y') {
        txt += "재무사항,";
    }
    if (v3 !== 'Y') {
        txt += "주식사항,";
    }
    if (v4 !== 'Y') {
        txt += "전문투자자,";
    }
    if (v5 !== 'Y') {
        txt += "CB발행,";
    }
    if (v6 !== 'Y') {
        txt += "BW발행,";
    }
    if (v7 !== 'Y') {
        txt += "회사채발행,";
    }
    if (ldMktTpCd === '2') {
        if (v9 !== 'Y') {
            txt += "벤처캐피탈,";
        }
    }
    if (v0 !== 'Y') {
        txt += "합병관련사항";
    }
    await $c.win.alert(txt + "을(를) 작성하지 않았습니다. \n해당사항이 없는 경우 해당사항이 없음 버튼을 클릭하십시오.");
};

